1	/**
2	 * Port of dataset/networkx/test5.py.
3	 *
4	 *   import argparse
5	 *   import networkx as nx
6	 *
7	 *   parser = argparse.ArgumentParser()
8	 *   parser.add_argument('--a', type=int, required=True)
9	 *   ... (--b, --c, --d, --e)
10	 *   args = parser.parse_args()
11	 *
12	 *   G = nx.DiGraph()
13	 *   G.add_edges_from([(args.a, args.b), (args.b, args.c), (args.c, args.d), (args.d, args.e)])
14	 *   print(nx.is_directed_acyclic_graph(G))
15	 *
16	 * Run it as: node test5.mjs --a 1 --b 2 --c 3 --d 4 --e 5
17	 */
