19	import { ArgumentParser } from './lib/argparse/index.mjs';
20	import * as nx from './lib/networkx/index.mjs';
21	import { int, pyStr, SystemExit } from './lib/python/index.mjs';
22	
23	function main() {
24	  const parser = new ArgumentParser();
25	  parser.add_argument('--a', { type: int, required: true });
26	  parser.add_argument('--b', { type: int, required: true });
27	  parser.add_argument('--c', { type: int, required: true });
28	  parser.add_argument('--d', { type: int, required: true });
29	  parser.add_argument('--e', { type: int, required: true });
30	  const args = parser.parse_args();
31	
32	  const G = new nx.DiGraph();
33	  G.add_edges_from([
34	    [args.a, args.b],
35	    [args.b, args.c],
36	    [args.c, args.d],
37	    [args.d, args.e],
38	  ]);
39	  console.log(pyStr(nx.is_directed_acyclic_graph(G))); // 检查是否为有向无环图
40	}
