20	 * narrower than `str.isspace()`: the C-level table used while scanning a
21	 * numeric literal does not include U+001C..U+001F, which is why `int('\x1c5')`
22	 * fails while `int('\x0b5')` succeeds.
23	 */
24	const ASCII_SPACES = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);
25	
26	/**
27	 * `Py_UNICODE_ISSPACE` for the code points above the ASCII range. These are the
28	 * characters that get folded to a plain space before a numeric literal is
29	 * scanned.
30	 */
31	const NON_ASCII_SPACES = new Set([
32	  0x0085, 0x00a0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
33	  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f,
34	  0x3000,
35	]);
36	
37	/** Memo table for {@link decimalValue}; digit runs are scanned at most once. */
38	const digitValues = new Map();
39	
40	export function isAsciiSpace(codePoint) {
41	  return ASCII_SPACES.has(codePoint);
42	}
43	
44	export function isNonAsciiSpace(codePoint) {
45	  return NON_ASCII_SPACES.has(codePoint);
46	}
47	
48	export function isDecimalDigit(codePoint) {
49	  return RE_DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
50	}
51	
52	export function isPrintable(codePoint) {
53	  if (codePoint === 0x20) return true;
54	  return !RE_NONPRINTABLE.test(String.fromCodePoint(codePoint));
55	}
56	
57	/**
58	 * `Py_UNICODE_TODECIMAL`: the numeric value of a decimal digit, or -1.
59	 *
60	 * Unicode lays every decimal digit set out as ten consecutive code points
61	 * starting at that script's ZERO, but consecutive sets can sit back to back --
62	 * the mathematical alphanumerics pack five of them into U+1D7CE..U+1D7FF. So
63	 * walking down to the first non-digit finds the head of the whole contiguous
64	 * block rather than of one set, and the offset has to be reduced modulo ten.
65	 */
66	export function decimalValue(codePoint) {
67	  const memo = digitValues.get(codePoint);
68	  if (memo !== undefined) return memo;
69	
70	  let value = -1;
71	  if (isDecimalDigit(codePoint)) {
72	    let blockStart = codePoint;
73	    while (blockStart > 0 && isDecimalDigit(blockStart - 1)) blockStart -= 1;
74	    value = (codePoint - blockStart) % 10;
75	  }
76	
77	  digitValues.set(codePoint, value);
78	  return value;
79	}
