18	  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
19	  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
20	  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
