23	/**
24	 * `repr()` of a string: single quotes unless the text contains a single quote
25	 * and no double quote, backslash/tab/newline/carriage-return escaped in short
26	 * form, and every non-printable code point escaped numerically.
27	 *
28	 * @param {string} text
29	 * @returns {string}
30	 */
31	export function reprString(text) {
32	  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
33	
34	  let out = quote;
35	  for (const character of text) {
36	    if (character === quote) {
37	      out += `\\${character}`;
38	      continue;
39	    }
40	    const short = SHORT_ESCAPES.get(character);
41	    if (short !== undefined) {
42	      out += short;
43	      continue;
44	    }
45	    const codePoint = character.codePointAt(0);
46	    out += isPrintable(codePoint) ? character : escapeCodePoint(codePoint);
47	  }
