59	  if (value === true) return 'True';
60	  if (value === false) return 'False';
61	  if (value === null || value === undefined) return 'None';
62	  if (typeof value === 'bigint') return value.toString();
63	  if (typeof value === 'string') return value;
64	  return String(value);
65	}
