67	/**
68	 * `repr()` of a value: like {@link pyStr} except strings come back quoted.
69	 *
70	 * @param {unknown} value
71	 * @returns {string}
72	 */
73	export function pyRepr(value) {
74	  if (typeof value === 'string') return reprString(value);
75	  return pyStr(value);
76	}
