12	const STDOUT = 1;
13	const STDERR = 2;
14	
15	function writeAll(fd, text) {
16	  const bytes = Buffer.from(text, 'utf8');
17	  let written = 0;
18	  while (written < bytes.length) {
19	    try {
20	      written += writeSync(fd, bytes, written, bytes.length - written);
21	    } catch (error) {
22	      // A non-blocking pipe that is momentarily full reports EAGAIN; retrying is
23	      // the only thing to do, and any other failure is genuinely fatal.
24	      if (error && (error.code === 'EAGAIN' || error.code === 'EWOULDBLOCK')) continue;
25	      throw error;
26	    }
27	  }
28	}
