16	/** Decode UTF-8, mapping every byte that cannot be decoded to U+DC00 + byte. */
17	function decodeSurrogateescape(bytes) {
18	  let out = '';
19	  let index = 0;
20	
21	  while (index < bytes.length) {
22	    const lead = bytes[index];
23	
24	    let length = 0;
25	    let codePoint = 0;
26	    let lowerBound = 0;
27	    if (lead < 0x80) {
28	      out += String.fromCharCode(lead);
29	      index += 1;
30	      continue;
31	    } else if (lead >= 0xc2 && lead <= 0xdf) {
32	      length = 2;
33	      codePoint = lead & 0x1f;
34	      lowerBound = 0x80;
35	    } else if (lead >= 0xe0 && lead <= 0xef) {
36	      length = 3;
37	      codePoint = lead & 0x0f;
38	      lowerBound = 0x800;
39	    } else if (lead >= 0xf0 && lead <= 0xf4) {
40	      length = 4;
41	      codePoint = lead & 0x07;
42	      lowerBound = 0x10000;
43	    } else {
44	      out += String.fromCharCode(0xdc00 + lead);
45	      index += 1;
46	      continue;
47	    }
48	
49	    let valid = index + length <= bytes.length;
50	    if (valid) {
51	      for (let offset = 1; offset < length; offset += 1) {
52	        const continuation = bytes[index + offset];
53	        if ((continuation & 0xc0) !== 0x80) {
54	          valid = false;
55	          break;
56	        }
57	        codePoint = (codePoint << 6) | (continuation & 0x3f);
58	      }
59	    }
60	    // Overlong forms, encoded surrogates and out-of-range code points are all
61	    // errors, and the error handler only ever consumes the leading byte.
62	    if (
63	      !valid ||
64	      codePoint < lowerBound ||
65	      codePoint > 0x10ffff ||
66	      (codePoint >= 0xd800 && codePoint <= 0xdfff)
67	    ) {
68	      out += String.fromCharCode(0xdc00 + lead);
69	      index += 1;
70	      continue;
71	    }
72	
73	    out += String.fromCodePoint(codePoint);
74	    index += length;
75	  }
76	
77	  return out;
78	}
