80	function readRawCommandLine() {
81	  const raw = readFileSync('/proc/self/cmdline');
82	  const fields = [];
83	  let start = 0;
84	  for (let index = 0; index < raw.length; index += 1) {
85	    if (raw[index] === 0) {
86	      fields.push(raw.subarray(start, index));
87	      start = index + 1;
88	    }
89	  }
90	  if (start < raw.length) fields.push(raw.subarray(start));
91	  return fields;
92	}
