101	
102	  try {
103	    const fields = readRawCommandLine();
104	    if (fields.length >= lossy.length) {
105	      const tail = fields.slice(fields.length - lossy.length);
106	      // Node strips its own options from process.argv, so only trust the raw
107	      // bytes when their lossy decoding reproduces what Node reported.
108	      const aligns = tail.every((bytes, i) => bytes.toString('utf8') === lossy[i]);
109	      if (aligns) return tail.map(decodeSurrogateescape);
110	    }
111	  } catch {
112	    // No procfs, or an unreadable cmdline: the lossy strings are good enough.
113	  }
114	
115	  return lossy;
116	}
