121	 *
122	 * @returns {string}
123	 */
124	export function getProgramName() {
125	  const script = process.argv[1];
126	  if (typeof script !== 'string' || script === '') return 'python';
127	  const segments = script.split('/');
128	  return segments[segments.length - 1] || script;
129	}
