44	  let end = spaceLeft;
45	  if (chunk.length > spaceLeft) {
46	    const hyphen = chunk.lastIndexOf('-', spaceLeft - 1);
47	    if (hyphen > 0 && [...chunk.slice(0, hyphen)].some((c) => c !== '-')) {
