68	  // Kept as a stack whose top is the last element, matching CPython's reversed
69	  // chunk list so that the control flow below can be compared line by line.
70	  const pending = splitChunks(text).reverse();
71	  const lines = [];
72	
73	  while (pending.length > 0) {
74	    const currentLine = [];
75	    let currentLength = 0;
76	
77	    if (isBlank(pending[pending.length - 1]) && lines.length > 0) pending.pop();
78	
79	    while (pending.length > 0) {
80	      const chunkLength = pending[pending.length - 1].length;
81	      if (currentLength + chunkLength > width) break;
82	      currentLine.push(pending.pop());
83	      currentLength += chunkLength;
84	    }
85	
86	    if (pending.length > 0 && pending[pending.length - 1].length > width) {
87	      handleLongWord(pending, currentLine, currentLength, width);
