76	      if (action.help === SUPPRESS) continue;
77	      let part;
78	      if (action.nargs === 0) {
79	        part = action.formatUsage();
80	      } else {
81	        part = `${action.optionStrings[0]} ${this._metavarFor(action)}`;
82	      }
83	      if (!action.required) part = `[${part}]`;
84	      parts.push(part);
85	    }
86	    return parts.join(' ');
87	  }
