89	  /**
90	   * `_format_usage`. The return value keeps the trailing blank line that the
91	   * section joiner later collapses.
92	   */
93	  formatUsage(actions, prefix = 'usage: ') {
94	    const prog = this._prog;
95	    const optionals = actions.filter((action) => action.optionStrings.length > 0);
96	    const positionals = actions.filter((action) => action.optionStrings.length === 0);
97	    const actionUsage = this._formatActionsUsage([...optionals, ...positionals]);
98	    let usage = [prog, actionUsage].filter((piece) => piece !== '').join(' ');
99	
100	    const textWidth = this._width - this._currentIndent;
101	    if (prefix.length + usage.length > textWidth) {
102	      const optionalParts = this._formatActionsUsage(optionals).match(USAGE_PART) ?? [];
103	      const positionalParts = this._formatActionsUsage(positionals).match(USAGE_PART) ?? [];
104	
105	      const getLines = (parts, indent, linePrefix = null) => {
106	        const lines = [];
107	        let line = [];
108	        let lineLength = (linePrefix === null ? indent.length : linePrefix.length) - 1;
109	        for (const part of parts) {
110	          if (lineLength + 1 + part.length > textWidth && line.length > 0) {
111	            lines.push(indent + line.join(' '));
112	            line = [];
113	            lineLength = indent.length - 1;
114	          }
115	          line.push(part);
116	          lineLength += 1 + part.length;
117	        }
118	        if (line.length > 0) lines.push(indent + line.join(' '));
119	        if (linePrefix !== null && lines.length > 0) {
120	          lines[0] = lines[0].slice(indent.length);
121	        }
122	        return lines;
123	      };
124	
125	      let lines;
126	      if (prefix.length + prog.length <= 0.75 * textWidth) {
127	        // Short program name: the first options sit right after it, and
128	        // continuation lines hang under that column.
129	        const indent = spaces(prefix.length + prog.length + 1);
130	        if (optionalParts.length > 0) {
131	          lines = getLines([prog, ...optionalParts], indent, prefix);
132	          lines.push(...getLines(positionalParts, indent));
133	        } else if (positionalParts.length > 0) {
134	          lines = getLines([prog, ...positionalParts], indent, prefix);
135	        } else {
136	          lines = [prog];
137	        }
138	      } else {
139	        // Long program name: it gets a line to itself.
140	        const indent = spaces(prefix.length);
141	        let wrapped = getLines([...optionalParts, ...positionalParts], indent);
142	        if (wrapped.length > 1) {
143	          wrapped = [...getLines(optionalParts, indent), ...getLines(positionalParts, indent)];
144	        }
145	        lines = [prog, ...wrapped];
146	      }
147	
148	      usage = lines.join('\n');
149	    }
150	
151	    return `${prefix}${usage}\n\n`;
152	  }
153	
154	  /** `_format_action`: one entry of the options list, help text included. */
155	  formatAction(action) {
156	    const helpPosition = Math.min(this._actionMaxLength + 2, this._maxHelpPosition);
157	    const helpWidth = Math.max(this._width - helpPosition, 11);
158	    const actionWidth = helpPosition - this._currentIndent - 2;
159	
160	    const invocation = this._formatActionInvocation(action);
161	    let header;
162	    let indentFirst = 0;
163	    if (!action.help) {
164	      header = `${spaces(this._currentIndent)}${invocation}\n`;
165	    } else if (invocation.length <= actionWidth) {
166	      header = `${spaces(this._currentIndent)}${invocation.padEnd(actionWidth)}  `;
167	      indentFirst = 0;
168	    } else {
169	      header = `${spaces(this._currentIndent)}${invocation}\n`;
170	      indentFirst = helpPosition;
171	    }
172	
173	    const parts = [header];
174	    if (action.help && action.help.trim() !== '') {
175	      const helpLines = wrap(action.help.replace(/\s+/g, ' ').trim(), helpWidth);
176	      if (helpLines.length > 0) {
177	        parts.push(`${spaces(indentFirst)}${helpLines[0]}\n`);
178	        for (const line of helpLines.slice(1)) {
179	          parts.push(`${spaces(helpPosition)}${line}\n`);
180	        }
181	      }
182	    } else if (!header.endsWith('\n')) {
183	      parts.push('\n');
184	    }
185	
186	    return parts.join('');
187	  }
