189	  /**
190	   * A titled block of entries. An empty block contributes nothing, which is why
191	   * the unused "positional arguments" group never shows up.
192	   */
193	  formatSection(heading, actions) {
194	    const visible = actions.filter((action) => action.help !== SUPPRESS);
195	    if (visible.length === 0) return '';
196	
197	    this._currentIndent += this._indentIncrement;
198	    const items = visible.map((action) => this.formatAction(action)).join('');
199	    this._currentIndent -= this._indentIncrement;
200	
201	    return `\n${spaces(this._currentIndent)}${heading}:\n${items}\n`;
202	  }
203	
204	  /** `format_help`: collapse runs of blank lines, then normalise the edges. */
205	  static finish(text) {
206	    if (text === '') return text;
207	    const collapsed = text.replace(LONG_BREAK, '\n\n');
208	    const trimmed = collapsed.replace(/^\n+/, '').replace(/\n+$/, '');
209	    return trimmed === '' ? '' : `${trimmed}\n`;
210	  }
